import{c as o,$ as i,Q as c,j as n,g as a,n as p,o as l,m as d}from"./chunks/framework.CWBTDBPu.js";const x=JSON.parse('{"title":"YuRelic 常见问题","description":"","frontmatter":{"title":"YuRelic 常见问题"},"headers":[],"relativePath":"plugins/items/yu-relic/faq.md","filePath":"plugins/items/yu-relic/faq.md"}'),r={name:"plugins/items/yu-relic/faq.md"},u={class:"quick-actions"};function h(g,e,y,b,m,k){const s=i("CopyMarkdownButton"),t=i("CopyLLMButton");return c(),n("div",null,[e[0]||(e[0]=a("h1",{id:"yurelic-常见问题",tabindex:"-1"},[p("YuRelic 常见问题 "),a("a",{class:"header-anchor",href:"#yurelic-常见问题","aria-label":'Permalink to "YuRelic 常见问题"'},"​")],-1)),a("div",u,[l(s,{page:""}),l(t,{page:""})]),e[1]||(e[1]=d(`<h2 id="物品不能开光" tabindex="-1">物品不能开光 <a class="header-anchor" href="#物品不能开光" aria-label="Permalink to &quot;物品不能开光&quot;">​</a></h2><p>先确认主手不是空气，且不是已经开光的灵器。然后让管理员执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/yurelic debugid</span></span></code></pre></div><p>常见原因：</p><ul><li>无法读取最大耐久。默认只有可损耗物品能开光。</li><li>混合端模组物品没有被分类规则识别，需要补 <code>custom-item-rules</code>。</li><li>无耐久物品没有加入 <code>rpg.non-durable-relics.whitelist</code>。</li><li>开光档位成本不足，例如 Vault 金币、PlayerPoints 点券或灵材不足。</li><li>物品剩余耐久太低，不能承载开光。</li></ul><h2 id="开光后不涨经验" tabindex="-1">开光后不涨经验 <a class="header-anchor" href="#开光后不涨经验" aria-label="Permalink to &quot;开光后不涨经验&quot;">​</a></h2><p>按顺序排查：</p><ol><li><code>/yurelic info</code> 看灵器是否为半损毁、封存、隔离或非当前器主。</li><li><code>/yurelic pact info</code> 看灵契是否回应当前玩家。</li><li><code>/yurelic breath</code> 看灵息疲劳是否严重衰减。</li><li><code>/yurelic scene</code> 看当前世界或区域是否禁成长。</li><li>确认行为真的消耗了物品耐久。YuRelic 默认有耐久门禁，防止无损刷经验。</li><li>如果是击杀经验，确认目标不是友好生物或被反刷规则压低收益。</li><li>如果依赖 LevelledMobs 倍率，执行 <code>/yurelic hooks</code> 看是否识别成功。</li></ol><h2 id="灵材不掉落" tabindex="-1">灵材不掉落 <a class="header-anchor" href="#灵材不掉落" aria-label="Permalink to &quot;灵材不掉落&quot;">​</a></h2><p>执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/yurelic loot</span></span>
<span class="line"><span>/yurelic loot simgui</span></span></code></pre></div><p>重点检查 <code>loot.enabled</code>、世界倍率、WorldGuard 区域倍率、MythicMobs ID、等级门槛、友好/中立生物门禁、每日额度和保底配置。正式服默认掉率较克制，<code>loot.max-final-chance</code> 会限制最终概率。</p><h2 id="动态依赖下载失败" tabindex="-1">动态依赖下载失败 <a class="header-anchor" href="#动态依赖下载失败" aria-label="Permalink to &quot;动态依赖下载失败&quot;">​</a></h2><p>执行 <code>/yurelic libs</code> 看具体依赖状态。离线服可以把依赖 jar 手动放入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/YuRelic/libs/</span></span></code></pre></div><p>如果是校验失败，确认 jar 完整；生产服不建议长期关闭 <code>library.verify-checksum</code>。</p><h2 id="mysql-或跨服数据异常" tabindex="-1">MySQL 或跨服数据异常 <a class="header-anchor" href="#mysql-或跨服数据异常" aria-label="Permalink to &quot;MySQL 或跨服数据异常&quot;">​</a></h2><p>执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/yurelic storage status</span></span>
<span class="line"><span>/yurelic doctor storage</span></span></code></pre></div><p>常见原因：</p><ul><li>MySQL 地址、端口、库名、账号或密码错误。</li><li>数据库用户没有建表或写入权限。</li><li>多个子服使用了相同 <code>storage.server-id</code>。</li><li>动态依赖中的 MySQL Connector 或 HikariCP 未加载。</li><li>网络防火墙阻止服务端连接数据库。</li></ul><h2 id="疑似复制或重复灵器-id" tabindex="-1">疑似复制或重复灵器 ID <a class="header-anchor" href="#疑似复制或重复灵器-id" aria-label="Permalink to &quot;疑似复制或重复灵器 ID&quot;">​</a></h2><p>先不要直接删除玩家物品。建议流程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/yurelic storage duplicates</span></span>
<span class="line"><span>/yurelic integrity scan</span></span>
<span class="line"><span>/yurelic integrity info</span></span>
<span class="line"><span>/yurelic integrity locks</span></span></code></pre></div><p>对可疑 ID 查看审计链、最后出现服务器、持有人和锁状态。确认误入库或作弊后，再用 <code>/yurelic purge &lt;灵器ID&gt;</code> 或 <code>/yurelic erasehand</code> 处理。</p><h2 id="placeholderapi-没有值" tabindex="-1">PlaceholderAPI 没有值 <a class="header-anchor" href="#placeholderapi-没有值" aria-label="Permalink to &quot;PlaceholderAPI 没有值&quot;">​</a></h2><p>执行 <code>/yurelic hooks</code>，确认 PlaceholderAPI 插件启用、API 可见、YuRelic 扩展已注册。</p><p>如果某个占位符为空，可能是：</p><ul><li>玩家主手没有灵器。</li><li>使用的是天榜占位符，但器藏/天榜暂无记录。</li><li><code>integrations.placeholderapi.empty</code> 被配置为空字符串。</li><li>服务器菜单插件缓存了旧值，需要刷新菜单或重载对应插件。</li></ul><h2 id="easybot-或-qq-群广播异常" tabindex="-1">EasyBot 或 QQ 群广播异常 <a class="header-anchor" href="#easybot-或-qq-群广播异常" aria-label="Permalink to &quot;EasyBot 或 QQ 群广播异常&quot;">​</a></h2><p>先看 <code>/yurelic hooks</code> 和 <code>/yurelic doctor hooks</code>。如果 RPC 不可用，检查 EasyBot 插件是否启用、BridgeClient 是否可见、目标插件 ID 与方法名是否匹配。</p><p>跨平台转发建议区分两类文本：</p><ul><li>游戏内公告：可以使用 MiniMessage、hover、click。</li><li>QQ 转发：建议使用纯文本或玩家聊天兜底，避免交互标签被原样发送。</li></ul><h2 id="gui-显示材质不对" tabindex="-1">GUI 显示材质不对 <a class="header-anchor" href="#gui-显示材质不对" aria-label="Permalink to &quot;GUI 显示材质不对&quot;">​</a></h2><p>GUI 材质解析会兼容旧版与现代材质名，但混合端仍可能有特殊物品。优先检查 <code>gui.pages.*</code> 中按钮材质；如果是灵器图标，确认物品的 <code>baseKey</code>、Material 或自定义规则能被当前服务端识别。</p><h2 id="升级后配置提示缺项" tabindex="-1">升级后配置提示缺项 <a class="header-anchor" href="#升级后配置提示缺项" aria-label="Permalink to &quot;升级后配置提示缺项&quot;">​</a></h2><p>这是正常的版本迁移保护。YuRelic 会在补全配置前备份旧文件到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/YuRelic/backups/</span></span></code></pre></div><p>执行 <code>/yurelic doctor config</code> 查看缺失项。深度自定义过的服，建议手动把新默认项合并到自己的配置，而不是直接覆盖旧文件。</p><h2 id="旧命令-yurpg-还能用吗" tabindex="-1">旧命令 <code>/yurpg</code> 还能用吗 <a class="header-anchor" href="#旧命令-yurpg-还能用吗" aria-label="Permalink to &quot;旧命令 \`/yurpg\` 还能用吗&quot;">​</a></h2><p>能。正式命名后主命令是 <code>/yurelic</code>，但 <code>/yurpg</code> 与 <code>/yrpg</code> 作为迁移兼容别名保留。新文档统一使用 <code>/yurelic</code>。</p><h2 id="不想让普通玩家做高风险操作" tabindex="-1">不想让普通玩家做高风险操作 <a class="header-anchor" href="#不想让普通玩家做高风险操作" aria-label="Permalink to &quot;不想让普通玩家做高风险操作&quot;">​</a></h2><p>限制对应权限，并在 GUI 中移除或隐藏按钮。尤其建议谨慎开放：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yurelic.salvage</span></span>
<span class="line"><span>yurelic.heritage</span></span>
<span class="line"><span>yurelic.seal</span></span>
<span class="line"><span>yurelic.guard</span></span>
<span class="line"><span>yurelic.market</span></span></code></pre></div><p>高危管理员权限如 <code>yurelic.purge</code>、<code>yurelic.open.admin</code>、<code>yurelic.exp.admin</code>、<code>yurelic.item.admin</code> 不应给普通玩家。</p>`,45))])}const q=o(r,[["render",h]]);export{x as __pageData,q as default};
